// План specs/job-payments.md 2.2 + 3.1 (кейсы .qa/tests/job-payments/JP-09, JP-10). Только Pre-Prod (Stripe test mode), десктоп Chrome, EN.
// #51cdcc: оплата по ссылке картой Stripe test 4242 → «Payment received», в работе Credit Card Ref pi_… Completed, ссылка Paid.
// #5bfdd1: такой платёж открывается только для просмотра — «Payment details», поля заблокированы, только Close.
// @writes @data @stripe-test: работа «QA-AUTO pay stripe … #67b4b4» ($5) + ссылка + платёж $5.00 (test mode, удалить нельзя —
// так и задумано). Порядок важен (serial): 3.1 смотрит платёж из 2.2. Очистка в afterAll: работа → Cancelled.
// На prod (app.techory.ai) — пропуск: реальная оплата.
import { test, expect, BrowserContext, Page } from '@playwright/test';
import {
  IS_PROD, PREPROD, REMAINING, amountRe, blockMessaging, cancelJob, createJobWithBalance, createPaymentLink, escRe,
  expectPayPage, historyRow, jobNumber, openCustomerContext, openPaymentsTab, openRoleContext, payOnStripeCheckout,
} from './payments-helpers';

test.describe('Job → Payments: Stripe payment by link (#51cdcc, #5bfdd1)', () => {
  test.describe.configure({ mode: 'serial' });
  test.skip(IS_PROD, 'оплата Stripe test — только Pre-Prod');

  let context: BrowserContext;
  let page: Page;
  let jobUrl: string | null = null;
  let messaging: string[] = [];

  test.beforeAll(async ({ browser }, testInfo) => {
    testInfo.setTimeout(180_000);
    ({ context, page } = await openRoleContext(browser, testInfo));
    messaging = await blockMessaging(page);
    jobUrl = await createJobWithBalance(page, 'stripe');
  });

  test.afterAll(async () => {
    expect(messaging, 'запросов отправки SMS/email быть не должно').toEqual([]);
    await cancelJob(page, jobUrl);
    await context?.close();
  });

  test('QA-AUTO: customer pays the link with Stripe test card 4242 — Payment received, Credit Card Ref pi_ Completed, link Paid #51cdcc @desktop @writes @data @stripe-test', async ({ browser }, testInfo) => {
    test.setTimeout(240_000);
    await openPaymentsTab(page, jobUrl!);
    const jobNo = await jobNumber(page);
    const link = await createPaymentLink(page);
    expect(link).toMatch(new RegExp(`^${escRe(PREPROD)}/pay\\?t=`));

    const customer = await openCustomerContext(browser, testInfo);
    try {
      // Шаг 1: клиент открывает ссылку → Pay $5.00 → Stripe Checkout (test) → 4242
      await customer.page.goto(link);
      await expectPayPage(customer.page, REMAINING, jobNo);
      await customer.page.getByRole('button', { name: `Pay ${REMAINING}` }).click();
      await payOnStripeAndReturn(customer.page);

      // Возврат на адрес среды /pay?…&paid=1 — «Payment received» («מה רצוי»: נפתח ומאפשר תשלום)
      await expect(customer.page).toHaveURL(new RegExp(`^${escRe(PREPROD)}/pay\\?.*paid=1`));
      await expect(customer.page.getByText('Payment received', { exact: true })).toBeVisible();
      await expect(customer.page.getByText(/has received your payment/)).toBeVisible();
      await expect(customer.page.getByText(amountRe(REMAINING)).first()).toBeVisible();
      await expect(customer.page.getByText(/^Paid on /)).toBeVisible();
    } finally {
      await customer.context.close();
    }

    // Шаг 2: в работе — платёж Credit Card Ref pi_… $5.00 Completed, ссылка Paid (статус приходит из Stripe — ждём с перезагрузкой)
    const stripeRow = historyRow(page, /Ref: pi_/);
    await expect(async () => {
      await openPaymentsTab(page, jobUrl!);
      await expect(stripeRow.filter({ hasText: 'Completed' })).toHaveCount(1, { timeout: 5_000 });
    }).toPass({ timeout: 90_000 });
    await expect(stripeRow).toContainText('Credit Card');
    await expect(stripeRow).toContainText(REMAINING);
    const main = page.getByRole('main');
    await expect(main.locator('div, li, tr').filter({ has: page.getByText(amountRe(REMAINING)) }).filter({ has: page.getByText('Paid', { exact: true }) }).last()).toBeVisible();
    await expect(main.getByText(/^Amount Paid:/).locator('..')).toContainText(REMAINING);
  });

  test('QA-AUTO: Stripe payment (Ref pi_) opens as read-only Payment details — fields disabled, only Close, no Save/Delete #5bfdd1 @desktop @writes @data @stripe-test', async () => {
    await openPaymentsTab(page, jobUrl!);
    const stripeRow = historyRow(page, /Ref: pi_/);
    await expect(stripeRow).toHaveCount(1);
    const ref = ((await stripeRow.innerText()).match(/pi_\w+/) || [''])[0];
    await stripeRow.click();

    // «Payment details» + пояснение про Stripe/Refund («מה רצוי»: אפשר רק לצפות; комментарий 10.11)
    const dialog = page.getByRole('dialog').filter({ hasText: 'Payment details' });
    await expect(dialog).toBeVisible();
    await expect(dialog.getByText(/This card payment went through Stripe, so it cannot be changed or deleted here/)).toBeVisible();
    await expect(dialog.getByText('Edit Payment', { exact: true })).toHaveCount(0);

    // Все поля заблокированы, Reference = pi_…
    const textboxes = dialog.getByRole('textbox');
    expect(await textboxes.count(), 'поля Amount / Reference / Notes').toBeGreaterThan(0);
    for (const tb of await textboxes.all()) await expect(tb).not.toBeEditable();
    for (const cb of await dialog.getByRole('combobox').all()) await expect(cb).toBeDisabled();
    const values = await Promise.all((await textboxes.all()).map((t) => t.inputValue()));
    expect(ref, 'Ref pi_ в строке истории').toMatch(/^pi_/);
    expect(values, 'Reference Number = pi_…').toContain(ref);

    // Только Close; Save и Delete нет
    await expect(dialog.getByRole('button', { name: /^Save$/ })).toHaveCount(0);
    await expect(dialog.getByRole('button', { name: /Delete/ })).toHaveCount(0);
    await dialog.getByRole('button', { name: /^Close$/ }).click();
    await expect(dialog).toBeHidden();

    // Платёж не изменился
    await expect(historyRow(page, ref)).toContainText('Completed');
  });
});

async function payOnStripeAndReturn(p: Page) {
  await payOnStripeCheckout(p);
  await p.waitForURL(new RegExp(`^${escRe(PREPROD)}/pay\\?.*paid=1`), { timeout: 90_000 });
}
